-- V4: personal planner (goals, tasks), achievements, in-app notifications,
-- group challenges and private groups with join requests.
--
-- Everything here is additive (expand only), so the previous release keeps working against
-- this schema during a rolling deploy.

-- ---------------------------------------------------------------------------------------
-- Private groups: a PRIVATE group is joined through a request the owner approves.
-- IF NOT EXISTS: a schema generated by Hibernate from the current entities already has them.
-- ---------------------------------------------------------------------------------------
alter table study_groups add column if not exists visibility varchar(16) not null default 'PUBLIC';
alter table study_groups add column if not exists description varchar(500);
alter table study_groups drop constraint if exists ck_study_groups_visibility;
alter table study_groups add constraint ck_study_groups_visibility check (visibility in ('PUBLIC', 'PRIVATE'));

create table group_join_requests (
    id          uuid         not null primary key,
    group_id    uuid         not null references study_groups (id) on delete cascade,
    user_id     uuid         not null references users (id) on delete cascade,
    message     varchar(500),
    status      varchar(16)  not null check (status in ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED')),
    created_at  timestamp(6) not null,
    decided_at  timestamp(6),
    decided_by  uuid references users (id) on delete set null
);
-- One open request per user and group; decided requests stay as history.
create unique index uq_group_join_requests_pending
    on group_join_requests (group_id, user_id) where status = 'PENDING';
create index idx_group_join_requests_user_status on group_join_requests (user_id, status);

-- ---------------------------------------------------------------------------------------
-- Study goals: a target per period (DAILY / WEEKLY / MONTHLY), overall or for one subject.
-- Replacing a goal deactivates the old row, so history is kept.
-- ---------------------------------------------------------------------------------------
create table study_goals (
    id              uuid         not null primary key,
    user_id         uuid         not null references users (id) on delete cascade,
    subject_id      uuid references subjects (id) on delete cascade,
    period          varchar(16)  not null check (period in ('DAILY', 'WEEKLY', 'MONTHLY')),
    target_seconds  integer      not null check (target_seconds > 0 and target_seconds <= 2678400),
    active          boolean      not null default true,
    created_at      timestamp(6) not null
);
-- At most one active goal per (user, period) overall and per (user, subject, period).
-- Two concurrent "set goal" requests can't both leave an active row behind.
create unique index uq_study_goals_active_overall
    on study_goals (user_id, period) where active and subject_id is null;
create unique index uq_study_goals_active_subject
    on study_goals (user_id, subject_id, period) where active and subject_id is not null;

-- ---------------------------------------------------------------------------------------
-- Study tasks: a to-do list, optionally tied to a subject.
-- ---------------------------------------------------------------------------------------
create table study_tasks (
    id                 uuid          not null primary key,
    user_id            uuid          not null references users (id) on delete cascade,
    subject_id         uuid references subjects (id) on delete set null,
    title              varchar(200)  not null,
    notes              varchar(2000),
    priority           varchar(16)   not null default 'MEDIUM' check (priority in ('LOW', 'MEDIUM', 'HIGH')),
    status             varchar(16)   not null default 'TODO' check (status in ('TODO', 'IN_PROGRESS', 'DONE')),
    due_date           date,
    estimated_minutes  integer check (estimated_minutes is null or (estimated_minutes > 0 and estimated_minutes <= 10000)),
    completed_at       timestamp(6),
    created_at         timestamp(6)  not null,
    updated_at         timestamp(6)  not null,
    -- completed_at is set exactly when the task is DONE
    constraint ck_study_tasks_completed_at check ((status = 'DONE') = (completed_at is not null))
);
create index idx_study_tasks_user_status_due on study_tasks (user_id, status, due_date);

-- ---------------------------------------------------------------------------------------
-- Achievements: a catalog (rows below) and what each user unlocked.
-- The rule is data: category + threshold, evaluated by AchievementService.
-- ---------------------------------------------------------------------------------------
create table achievements (
    code         varchar(64)  not null primary key,
    name         varchar(100) not null,
    description  varchar(255) not null,
    icon         varchar(64)  not null,
    category     varchar(32)  not null,
    threshold    integer      not null,
    sort_order   integer      not null
);

create table user_achievements (
    id                uuid         not null primary key,
    user_id           uuid         not null references users (id) on delete cascade,
    achievement_code  varchar(64)  not null references achievements (code),
    unlocked_at       timestamp(6) not null,
    -- unlocking is INSERT ... ON CONFLICT DO NOTHING: concurrent evaluations unlock (and notify) once
    constraint uq_user_achievements_user_code unique (user_id, achievement_code)
);

