-- ---------------------------------------------------------------------------------------
-- In-app notifications (achievement unlocked, join request decided, added to a group, ...)
-- ---------------------------------------------------------------------------------------
create table notifications (
    id          uuid          not null primary key,
    user_id     uuid          not null references users (id) on delete cascade,
    type        varchar(32)   not null,
    title       varchar(200)  not null,
    message     varchar(1000),
    link        varchar(255),
    read_at     timestamp(6),
    created_at  timestamp(6)  not null
);
create index idx_notifications_user_created on notifications (user_id, created_at desc);
-- the bell polls the unread count: a partial index keeps that lookup tiny
create index idx_notifications_user_unread on notifications (user_id) where read_at is null;

-- ---------------------------------------------------------------------------------------
-- Group challenges: "study N hours between two dates", progress computed from sessions.
-- ---------------------------------------------------------------------------------------
create table group_challenges (
    id              uuid          not null primary key,
    group_id        uuid          not null references study_groups (id) on delete cascade,
    created_by      uuid          not null references users (id) on delete cascade,
    title           varchar(200)  not null,
    description     varchar(1000),
    target_seconds  integer       not null check (target_seconds > 0),
    start_date      date          not null,
    end_date        date          not null,
    created_at      timestamp(6)  not null,
    constraint ck_group_challenges_dates check (end_date >= start_date)
);
create index idx_group_challenges_group_end on group_challenges (group_id, end_date);
